  "steps": [
    {
      "id": 1,
      "claim": "American federalism is the constitutional division of authority between the national government and the states.",
      "evidence": "Political‑science definition of federalism; U.S. Constitution allocates specific powers to the federal government (Art. I §8) and reserves the remainder to the states (10th Amendment).",
      "weight": 0.25,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "An illustration of federalism must show this division of power between national and state governments.",
      "evidence": "By definition, any example of federalism demonstrates how authority is shared or separated between the two levels of government.",
      "weight": 0.20,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Option A (checks and balances among the three branches) concerns separation of powers within the federal government, not between national and state governments.",
      "evidence": "Checks and balances allocate authority among executive, legislative, and judicial branches per Articles I‑III; they do not involve state authority.",
      "weight": 0.15,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "Option B (process by which international treaties are completed) is an exclusive federal function and does not involve the states.",
      "evidence": "Treaty‑making power resides with the President and Senate (Art. II §2; Art. I §8) with no constitutional role for states.",
      "weight": 0.15,
      "depends_on": [2]
    },
    {
      "id": 5,
      "claim": "Option C (special constitutional status of Washington, D.C.) deals with a federal district, not a power‑sharing arrangement between federal and state governments.",
      "evidence": "Article I §8, cl. 17 gives Congress exclusive jurisdiction over the District of Columbia; it is not a state and does not illustrate federal‑state division.",
      "weight": 0.10,
      "depends_on": [2]
    },
    {
      "id": 6,
      "claim": "Option D (the Tenth Amendment) explicitly reserves to the states all powers not delegated to the United States, directly embodying federalism.",
      "evidence": "Text of the Tenth Amendment: “The powers not delegated to the United States… are reserved to the States respectively, or to the people.”",
      "weight": 0.30,
      "depends_on": [2]
    },
    {
      "id": 7,
      "claim": "Because the Tenth Amendment directly reflects the constitutional division of power between national and state governments, it most clearly exemplifies American federalism.",
      "evidence": "Steps 2 and 6 show that D satisfies the definition of federalism while A, B, and C do not.",
      "weight": 0.05,
      "depends_on": [2, 6]
    }
  ],
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Describes separation of powers within the national government, not the national‑state power split that defines federalism."
    },
    {
      "answer": "B",
      "reason_rejected": "Treaty‑making is an exclusive federal power and involves no state authority."
    },
    {
      "answer": "C",
      "reason_rejected": "The status of Washington, D.C. concerns a federal district under congressional control, not a shared sovereignty arrangement."
    }
  ]
